package com.shopsphere;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.UUID;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/inventory")public class InventoryController{private final InventoryService service;InventoryController(InventoryService s){service=s;}record Quantity(@Positive int quantity){}record Stock(@NotBlank String sku,@PositiveOrZero int quantityAvailable,@PositiveOrZero int reorderLevel){}@GetMapping("/{productId}")Inventory get(@PathVariable UUID productId){return service.get(productId);}@PostMapping("/{productId}/reserve")Inventory reserve(@PathVariable UUID productId,@Valid@RequestBody Quantity r){return service.reserve(productId,r.quantity());}@PostMapping("/{productId}/release")Inventory release(@PathVariable UUID productId,@Valid@RequestBody Quantity r){return service.release(productId,r.quantity());}@PutMapping("/{productId}/stock")Inventory stock(@PathVariable UUID productId,@Valid@RequestBody Stock r){return service.set(productId,r.sku(),r.quantityAvailable(),r.reorderLevel());}}
